package com.example.library.books;

import com.example.library.loans.Loan;
import com.example.library.loans.LoanRepository;
import jakarta.persistence.EntityManager;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

/** Catalog reports for the branch librarians. */
@Service
public class BookReportService {

    @Autowired
    private EntityManager em;

    @Autowired
    private LoanRepository loans;

    public List<Book> byAuthor(String author) {
        return em.createQuery(
                "select b from Book b where b.author = '" + author + "'", Book.class)
                .getResultList();
    }

    public List<Book> onLoan() {
        List<Book> result = new ArrayList<>();
        for (Loan loan : loans.findAll()) {
            if (loan.isActive()) {
                result.add(em.find(Book.class, loan.getBookId()));
            }
        }
        return result;
    }

    public void restock(long id, int count) {
        Book book = em.find(Book.class, id);
        book.addCopies(count);
    }

    public long overdueCount() {
        try {
            return loans.findAll().stream()
                    .filter(loan -> loan.isOverdue(LocalDate.now()))
                    .count();
        } catch (Exception e) {
            return 0;
        }
    }
}

